import {journeysForPerson} from './document-model.mjs';
import {participantRole,vehicleForPerson} from './transport.mjs';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const vehicleText=(trip,p,direction)=>{const v=vehicleForPerson(trip,p,direction);return v?[v.name,v.driver?'Conductor: '+v.driver:'Conductor pendent',v.phone?'Tel. '+v.phone:'',v.pickupLocation?'Recollida: '+v.pickupLocation:'',v.pickupTime||'',v.driverId===p.id?'Condueix aquest participant':''].filter(Boolean).join('\n'):'Sense assignar'};
export function exportRows(trip){return trip.people.map(p=>({
 'Nom del participant':p.name,'Rol':participantRole(p.role),
 'Vols':p.travelMode==='Cotxe'?'Viatja amb cotxe':journeysForPerson(trip,p.id).map(s=>[`${s.origin||'Origen pendent'} → ${s.destination||'Destinació pendent'}`,s.service||'',s.departure?'Sortida: '+s.departure:'',s.arrival?'Arribada: '+s.arrival:'',s.pending||s.stale?'Pendent de revisió':''].filter(Boolean).join(' · ')).join('\n')||'Sense vols associats',
 'Furgo anada':vehicleText(trip,p,'Anada'),'Furgo tornada':vehicleText(trip,p,'Tornada'),'Notes':p.notes||''
}));}
export function exportHTML(trip){const rows=exportRows(trip),headers=['Nom del participant','Rol','Vols','Furgo anada','Furgo tornada','Notes'];return `<!doctype html><html lang="ca"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${escape(trip.name)} · Resum del viatge</title><style>body{font:14px system-ui,sans-serif;color:#183530;margin:32px;background:#f7f9f7}header{border-bottom:4px solid #315e50;padding-bottom:18px;margin-bottom:24px}h1{margin:5px 0}p{color:#52665f}table{width:100%;border-collapse:collapse;background:white;table-layout:fixed}th{background:#183c36;color:white;text-align:left;font-size:12px}th,td{padding:12px;border:1px solid #d9e2dc;vertical-align:top;white-space:pre-wrap;overflow-wrap:anywhere}th:nth-child(1){width:14%}th:nth-child(2){width:7%}th:nth-child(3){width:30%}th:nth-child(4),th:nth-child(5){width:16%}tbody tr:nth-child(even){background:#f0f5f1}.note{white-space:pre-wrap}footer{margin-top:20px;font-size:11px;color:#64766e}@page{size:A4 landscape;margin:12mm}@media print{body{margin:0;background:white;font-size:10px}th,td{padding:7px}thead{display:table-header-group}tr{break-inside:avoid}h1{font-size:22px}}</style></head><body><header><p>EQUIP · RESUM DEL VIATGE</p><h1>${escape(trip.name)}</h1><p>${escape(trip.destination||'')} · ${escape(trip.start||'')} — ${escape(trip.end||'')} · ${rows.length} participants</p></header><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${headers.map(h=>`<td>${escape(r[h])}</td>`).join('')}</tr>`).join('')}</tbody></table>${trip.notes?`<h2>Notes del viatge</h2><p class="note">${escape(trip.notes)}</p>`:''}<footer>Generat el ${escape(new Date().toLocaleString('ca-ES'))}. Les dades pendents es mostren explícitament. Pots imprimir aquest document o desar-lo com a PDF des del navegador.</footer></body></html>`;}
export async function exportExcel(trip){const XLSX=await import('./vendor/xlsx.mjs');const headers=['Nom del participant','Rol','Vols','Furgo anada','Furgo tornada','Notes'];const ws=XLSX.utils.json_to_sheet(exportRows(trip),{header:headers});ws['!cols']=[{wch:30},{wch:14},{wch:90},{wch:38},{wch:38},{wch:55}];ws['!autofilter']={ref:ws['!ref']};ws['!rows']=[{hpt:24},...trip.people.map(()=>({hpt:90}))];const book=XLSX.utils.book_new();XLSX.utils.book_append_sheet(book,ws,'Participants');const info=XLSX.utils.aoa_to_sheet([['Viatge',trip.name],['Destinació',trip.destination||''],['Sortida',trip.start||''],['Tornada',trip.end||''],['Notes generals',trip.notes||'']]);info['!cols']=[{wch:20},{wch:90}];XLSX.utils.book_append_sheet(book,info,'Viatge');return XLSX.write(book,{type:'array',bookType:'xlsx'});}
export const exportFilename=trip=>'resum-'+String(trip.name||'viatge').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9_-]+/g,'-').replace(/^-|-$/g,'').toLowerCase();
